// Üretilen dosya: tool/ozgun/uret.py. Fizik · Dalgalar, ses ve optik hesapları (zor).
const ozPhysics13Zor = <(String, String, List<String>, String)>[
  ('Bir ipte y = 0,02·sin(50t − 5x) denklemli dalga ilerliyor (SI). İp parçacıklarının ulaştığı en büyük enine hız kaç m/s\'dir?', '1', ['10', '0,1', '250'], 'Parçacıkların en büyük enine hızı A·ω\'dır. 0,02 × 50 = 1 m/s olur; dalga hızı (10 m/s) ile karıştırılmamalıdır.'),
  ('Noktasal bir kaynaktan çıkan küresel dalgada kaynağa uzaklık üç katına çıkarsa dalganın genliği (enerji kaybı yok) nasıl değişir?', 'Üçte birine iner', ['Dokuzda birine iner', 'Yarıya iner', 'Değişmez'], 'Şiddet 1/r² ile azalır; şiddet genliğin karesiyle orantılı olduğundan genlik 1/r ile azalır, yani üçte birine iner.'),
  ('Boyu L olan bir ipin tamamı bir ucundan asılıyken kendi ağırlığıyla gerilmiştir. Aşağıdan yukarıya doğru çıkıldıkça enine dalgaların hızı nasıl değişir?', 'Artar, çünkü gerilme yukarıda büyüktür', ['Azalır, çünkü gerilme yukarıda büyüktür', 'Değişmez, çünkü ip homojendir', 'Önce artar sonra azalır'], 'Yukarı noktalar altındaki ipin ağırlığını da taşıdığından gerilme yukarıda büyüktür; v = √(T/μ) yukarı doğru artar.'),
  ('Bir yay üzerinde sağa doğru ilerleyen, tepesi yukarı bakan üçgen bir atmanın önü ile arkasında yay parçacıkları hangi yönde hareket eder?', 'Önündeki yukarı, arkasındakiler aşağı', ['Önündeki aşağı, arkasındakiler yukarı', 'Tüm parçacıklar atmanın tepesiyle birlikte yukarı doğru hareket eder', 'Tüm parçacıklar aşağı'], 'Atma ilerledikçe önündeki parçacıklar tepeye katılmak için yukarı çıkar, arkadakiler denge konumuna dönmek için aşağı iner.'),
  ('Boyu 0,5 m ve kütlesi 2 g olan bir tel 40 N ile geriliyor. Telin temel frekansı kaç Hz\'dir?', '100', ['200,5', '50', '400'], 'μ = 0,002/0,5 = 0,004 kg/m; v = √(40/0,004) = √10000 = 100 m/s. f₁ = v/2L = 100/1 = 100 Hz\'dir.'),
  ('Aynı malzemeden, aynı boy ve gerilmede iki telden birinin yarıçapı ötekinin iki katıdır. Kalın telin temel frekansı inceye göre kaç kat olur?', '1/2', ['2, çünkü kütle arttıkça frekans artar', '1/4', '4'], 'Kütle/uzunluk yarıçapın karesiyle orantılı olduğundan μ kalın telde 4 kat büyüktür; f ∝ 1/√μ olduğundan frekans yarıya iner.'),
  ('Telli bir sazda tele hafifçe orta noktasından dokunup yay sürüldüğünde tel hangi harmoniği vererek \'flajolet\' sesi çıkarır?', 'İkinci harmoniği, çünkü orta noktada düğüm zorlanır', ['Temel harmoniği, çünkü orta noktada karın oluşması zorlanır', 'Yalnızca üçüncü harmoniği', 'Frekansı sıfır olan sesi'], 'Orta noktadaki hafif dokunuş orada düğüm oluşturur; böylece tek karınlı temel mod bastırılır ve ikinci harmonik duyulur.'),
  ('Aynı bölgede iki düğüm arasında yer alan farklı noktaların titreşim genlikleri için hangisi doğrudur?', 'Genlikler farklı, ama tüm noktalar aynı fazdadır', ['Genlikler aynı, fazlar farklıdır', 'Hem genlikler hem fazlar aynıdır', 'Genlik ve fazlar rastgeledir, düzenli bir dağılım göstermez'], 'Duran dalgada konuma bağlı genlik 2A·|sin(kx)| gibidir; iki düğüm arasında genlik değişir, ancak tüm noktalar aynı anda denge konumundan geçer.'),
  ('Derinliği 4000 m olan bir okyanus bölgesinde tsunami dalgasının hızı v = √(g·h) ile (g = 10 m/s²) kaç km/saattir?', '720', ['200', '72', '2000'], 'v = √(10 × 4000) = 200 m/s = 200 × 3,6 = 720 km/saat bulunur.'),
  ('Derinliği 40 m olan sığ kıyı şeridine giren bir tsunami dalgasının hızı, 4000 m derinlikteki hızının kaçta kaçına düşer? (v ∝ √h)', 'Onda birine', ['Yüzde birine', 'Yarısına', 'Yüzde onuna'], 'Hız √h ile orantılıdır; derinlik 100 kat azalınca hız √100 = 10 kat, yani onda birine iner.'),
  ('Dalga leğeninde dalgalar 1. bölgeden 2. bölgeye geçerken dalga boyu 6 cm\'den 4 cm\'ye düşüyor. Bu geçişte dalga cephelerinin sınırla yaptığı açı için ne söylenir?', 'Kırılma sonrasında açı küçülür', ['Kırılma sonrasında açı büyür', 'Açı değişmez, çünkü frekans aynı kalır', 'Cephe sınıra dik olur'], 'Dalga boyu ve hız azaldığında dalga normale yaklaşır; cephenin sınırla yaptığı açı da aynı oranda küçülür (sinθ₁/sinθ₂ = λ₁/λ₂).'),
  ('Bir depremde P dalgalarının hızı 8 km/s, S dalgalarının hızı 4,5 km/s olarak alınıyor. Deprem merkezine 360 km uzaklıktaki bir istasyonda iki dalganın varış zamanları arasındaki fark yaklaşık kaç saniyedir?', '35', ['20,5', '45', '80'], 'P için t = 360/8 = 45 s; S için t = 360/4,5 = 80 s. Fark 80 − 45 = 35 s\'dir.'),
  ('Rayleigh yüzey dalgasında yer parçacıklarının hareketi nasıldır?', 'Düşey düzlemde elips biçimli, yuvarlanır gibi', ['Yalnız dalga yönünde ileri geri, boyuna dalga gibi', 'Yalnız yatay ve dalga yönüne dik', 'Hareketsiz kalır'], 'Rayleigh dalgasında parçacıklar düşey düzlemde elips çizerek hareket eder; denizdeki dalgalara benzer.'),
  ('Su dalgalarında dalga boyu derinliğe göre kısa ise (derin su) dalga hızı neye bağlıdır?', 'Dalga boyuna, daha uzun dalgalar daha hızlı gider', ['Derinliğe, çünkü daha derin sudaki dalgalar her zaman daha hızlıdır', 'Dalganın genliğine', 'Suyun sıcaklığına yalnız'], 'Derin su dalgalarında v = √(gλ/2π) olduğundan uzun dalga boylu dalgalar daha hızlı ilerler; derinlik etkisizdir.'),
  ('Bir deprem istasyonu P dalgasını S dalgasından 24 s önce kaydediyor. P hızı 7,5 km/s, S hızı 4,5 km/s ise merkez üssü yaklaşık kaç km uzaktadır?', '270', ['180,5', '108', '54'], 'd(1/4,5 − 1/7,5) = 24 → d·(0,2222−0,1333) = 24 → d·0,0889 = 24 → d = 270 km.'),
  ('İnsan kulağında şiddet düzeyi yaklaşık 10 dB artınca sesin \'iki kat daha yüksek\' algılandığı söylenir. Bu algı ile şiddet oranı arasındaki ilişki için ne söylenebilir?', 'Algı, şiddetle doğrusal değil logaritmik biçimde artar', ['Algı şiddetle doğru orantılıdır', 'Algı şiddetin karesiyle artar, bu yüzden 10 dB iki kat gürültü demektir', 'Algı şiddetten bağımsızdır'], '10 dB artış şiddetin 10 katına karşılık gelir ama algı yalnız iki katı kadardır; kulak yaklaşık logaritmik algılar.'),
  ('Süpersonik bir jetin şok dalgası konisinin yarım tepe açısı büyüdükçe jetin hızı için ne söylenebilir?', 'Azalıyordur, ses hızına yaklaşıyordur', ['Artıyordur, çünkü daha geniş koni daha hızlı demektir', 'Açı hızı etkilemez', 'Hız sıfırdır'], 'sinθ = v_ses/v_uçak; θ büyürse sinθ büyür, bu da v_uçak\'ın ses hızına yaklaştığı anlamına gelir.'),
  ('Bir deniz fenerinde sis düdüğü, fırtınalı havada rüzgâr yönünde uzaktan duyulurken ters yönde daha az duyulur. Bunun fiziksel nedeni nedir?', 'Rüzgâr, ses dalgalarının etkin hızını ve yönünü değiştirerek kırılmalarına yol açar', ['Rüzgâr sesin frekansını düşürerek ters yönde duyulan sesi kalınlaştırır ve belirgin biçimde zayıflatır', 'Düdüğün gücü rüzgârla değişir', 'Ses boşlukta hareket eder'], 'Rüzgâr hızı ses hızına eklenir ya da çıkarılır; yüksekliğe göre rüzgâr değişimi ses cephelerini yere ya da yukarı doğru kırar.'),
  ('Geceleri uzaktaki seslerin gündüze göre daha net duyulmasında hangi olay rol oynar?', 'Soğuk yer yüzeyi yakınında sesin yere doğru kırılması', ['Sesin frekansının geceleri artması nedeniyle daha uzağa ulaşması', 'Hava moleküllerinin duran dalga yapması', 'Sesin uzaktan yansımasının azalması'], 'Geceleri yer katmanı soğuk, üst katman sıcaktır; ses hızı yukarıda büyük olduğundan ses cepheleri yere doğru bükülür.'),
  ('İki ucu açık L uzunluğunda bir borunun üçüncü harmonik frekansı, bir ucu kapalı aynı uzunluktaki borunun üçüncü rezonans frekansının kaç katıdır? (Ses hızı aynı)', '6/5', ['3/2', '2, çünkü açık boruda frekans iki katıdır', '1'], 'Açık boru: f = 3v/2L. Kapalı boru üçüncü rezonans (5. harmonik): 5v/4L. Oran = (3/2L)/(5/4L) = 6/5\'tir.'),
  ('Bir ucu kapalı bir borunun açık ucuna yakın bölgede hava molekülleri için duran dalgada hangi durum vardır?', 'Yer değiştirme karını, basınç düğümü', ['Yer değiştirme düğümü, basınç karını', 'Hem yer değiştirme hem basınç düğümü', 'Hem yer değiştirme hem basınç karını oluşturur'], 'Açık uç atmosfere açık olduğundan basınç sabittir (basınç düğümü), moleküller serbest titreşir (yer değiştirme karını).'),
  ('Kapalı uçta ise ses basıncı değişimi nasıl olur?', 'Basınç değişimi karında en büyük, yer değiştirme düğümündedir', ['Basınç değişimi sıfırdır, çünkü kapalı uçta hava hareketsiz kalır', 'Hem basınç hem yer değiştirme sıfırdır', 'Hem basınç hem yer değiştirme büyüktür'], 'Kapalı uçta moleküller hareket edemez (yer değiştirme düğümü); basınç değişimi ise en büyüktür.'),
  ('Ses hızının 340 m/s olduğu havada 700 Hz\'lik ses veren bir kaynak 10 m/s hızla gözlemciye yaklaşırken gözlemci de kaynağa doğru 10 m/s ile yaklaşıyor. Gözlemcinin duyduğu frekans yaklaşık kaç Hz\'dir?', '742', ['720,5', '700', '765'], 'f\' = f(v + v_o)/(v − v_s) = 700 × 350/330 ≈ 742 Hz.'),
  ('Duran bir yansıtıcı duvara 20 m/s hızla yaklaşan bir araç 500 Hz\'lik korna çalıyor. Duvardan yansıyıp araca dönen sesin araçtaki gözlemci tarafından algılanan frekansı yaklaşık kaç Hz\'dir? (Ses hızı 340 m/s)', '562', ['531,5', '500', '625'], 'Duvar önce f₁ = 500·340/320 = 531,25 Hz alır ve yansıtır. Araç bu kaynağa yaklaştığından f₂ = 531,25·360/340 ≈ 562 Hz duyar.'),
  ('Frekansı 10 GHz olan bir trafik radarı yaklaşan bir araçtan yansıyan dalgayı alıyor ve frekans kaymasını 2000 Hz ölçüyor. Araç yaklaşık kaç m/s hızla gelmektedir? (c = 3 × 10⁸ m/s, Δf = 2fv/c)', '30', ['15,5', '60', '3'], 'Δf = 2fv/c → v = Δf·c/(2f) = 2000 × 3 × 10⁸/(2 × 10¹⁰) = 30 m/s.'),
  ('Kaynak sabitken gözlemci kaynaktan uzaklaşıyor. Gözlemcinin bulunduğu ortamda ardışık ses cepheleri arasındaki uzaklık (dalga boyu) için ne söylenir?', 'Değişmez; yalnız algılanan frekans azalır', ['Uzar, çünkü gözlemci uzaklaşırken cepheler arası mesafe büyür', 'Kısalır, çünkü gözlemci cepheleri daha seyrek yakalar', 'Sıfır olur, çünkü gözlemci dalganın hızından kaçar'], 'Dalga boyunu kaynağın hareketi belirler. Gözlemci hareketi yalnız cepheleri yakalama sıklığını (frekansı) değiştirir; dalga boyu aynı kalır.'),
  ('Bir gökada Dünya\'dan uzaklaşırken hidrojenin 656 nm\'lik çizgisi 721,6 nm\'de gözleniyor. Bu gökadanın uzaklaşma hızı ışık hızının yaklaşık kaçta kaçıdır? (v/c = Δλ/λ)', 'Onda biri', ['Yüzde biri', 'Yarısı', 'Binde biri'], 'Δλ = 65,6 nm; Δλ/λ = 65,6/656 = 0,1 olduğundan v ≈ 0,1c\'dir.'),
  ('Düzlem ayna karşısında duran bir kişi, aynadaki görüntüsünü \'sağ-sol\' yer değiştirmiş değil de \'ön-arka\' yer değiştirmiş olarak yorumlamalıdır. Bu görüş neye dayanır?', 'Aynanın yalnızca ayna yüzeyine dik doğrultuyu ters çevirmesine', ['Aynanın sağı ve solu kendiliğinden değiştirmesine, çünkü ayna soldan sağa yansıtır', 'Aynada ışığın kırılmasına', 'Aynanın görüntüyü büyütmesine'], 'Düzlem ayna yalnızca yüzeye dik ekseni (ön-arka) ters çevirir; yatay ve düşey eksenler değişmez. Sağ-sol değişimi algısal bir yorumdur.'),
  ('Bir çukur aynanın eğrilik yarıçapı 60 cm\'dir. Asal eksen üzerinde aynadan 20 cm uzağa konan cismin görüntüsü nerede ve nasıl oluşur?', 'Aynanın arkasında 60 cm uzakta, sanal ve düz', ['Aynanın önünde 60 cm uzakta, gerçek ve ters', 'Aynanın arkasında 12 cm uzakta, sanal ve küçük', 'Aynanın önünde 12 cm uzakta, gerçek ve küçük'], 'f = R/2 = 30 cm. Cisim f içinde (20 cm). 1/s\' = 1/f − 1/s = 1/30 − 1/20 = −1/60 → s\' = −60 cm; görüntü sanal, düz ve büyüktür.'),
  ('Tümsek bir aynanın eğrilik yarıçapı 40 cm\'dir. Aynadan 20 cm uzaktaki cismin görüntüsü aynanın arkasında kaç cm uzaklıkta oluşur?', '10', ['20', '13,3', '40'], '|f| = 20 cm; tümsek ayna için f = −20. 1/s\' = 1/f − 1/s = −1/20 − 1/20 = −1/10 → s\' = −10 cm; görüntü arkada 10 cm\'dedir.'),
  ('Bir çukur aynada cisim sonsuz uzaklıktan merkeze doğru yaklaştırılırken görüntünün büyütme oranı (|m|) için ne söylenir?', 'Sürekli artarak 1\'e ulaşır', ['Sürekli azalır', 'Sabit kalır', 'Önce artar sonra azalarak sıfıra yaklaşır'], 'Uzak cisim odakta küçük bir görüntü verir; yaklaştıkça görüntü büyür ve cisim merkezde iken |m| = 1 olur.'),
  ('Küresel aynalarda \'asal eksene yakın ışınlar\' koşulunun öğretilmesinin nedeni nedir?', 'Geniş açılı ışınlar tek noktada toplanmayıp küresel sapınç denen bozulma verir', ['Işınlar asal eksenden uzaklaştıkça hızları değiştiği için görüntü bulanıklaşır ve netlik tamamen kaybolur', 'Yakın ışınlar daha parlak yansır', 'Geniş açılı ışınlar aynada soğurulur'], 'Küresel yüzeyde asal eksenden uzak ışınlar odaktan farklı noktalara yansır (küresel sapınç); bu yüzden büyük teleskoplarda paraboloit ayna kullanılır.'),
  ('Odak uzaklığı 12 cm olan bir çukur aynayla 4 cm yüksekliğindeki bir cismin 8 cm yüksekliğinde düz bir görüntüsü isteniyor. Cisim aynadan kaç cm uzağa konmalıdır?', '6', ['24', '12', '3'], 'Sanal ve düz için m = +2 = f/(f − s) → 2(12 − s) = 12 → s = 6 cm.'),
  ('Havadan suya dalarak balık yakalamaya çalışan bir balıkçıl kuşu, suyun içindeki balığa gagasını nereye yöneltmelidir?', 'Balığın görünür konumunun biraz altına', ['Balığın görünür konumunun biraz üstüne ve yüzeye doğru', 'Balığın tam görünür konumuna', 'Balığın görünür konumunun yan tarafına'], 'Balık görünenden daha derindedir; ışınlar yüzeyde normalden uzaklaşarak kırıldığından gerçek konum, görünen konumun altındadır.'),
  ('Yanal kayma (öteleme) miktarı paralel yüzlü bir levhada hangi nicelik arttıkça artar?', 'Levhanın kalınlığı ve gelme açısı', ['Levhanın genişliği', 'Işığın şiddeti ile levhanın yoğunluğu ve rengi', 'Levhanın rengi'], 'Yanal kayma d = t·sin(i − r)/cos r bağıntısıyla verilir; kalınlık ve gelme açısı arttıkça kayma artar.'),
  ('Hava (n = 1), su (n = 4/3), cam (n = 3/2) katmanlı bir düzenekte ışık havadan cama su katmanı üzerinden geçecektir. Işın cama girerken kırılma açısı hangi niceliğe bağlıdır?', 'Yalnız hava ile cam arasındaki indislere; ara su katmanı sonucu değiştirmez', ['Yalnız suyun kırılma indisine', 'Su ve camın indislerinin toplamına, çünkü her katmandaki sapmalar birbirine eklenir ve sonuç ara katmana bağlıdır', 'Üç indisin çarpımına'], 'Paralel katmanlarda n·sinθ sabit kalır; ara ortam sonuç açıyı etkilemez, yalnız ilk ve son indis önemlidir.'),
  ('Kırılma indisi 5/3 olan bir sıvıda, yüzeyin 4 m altındaki noktasal ışık kaynağı havaya ışık gönderiyor. Yüzeyde ışığın dışarı çıkabildiği dairenin yarıçapı kaç m\'dir?', '3', ['4', '2,4', '5'], 'sinθ_c = 0,6 → tanθ_c = 0,75. r = h·tanθ_c = 4 × 0,75 = 3 m\'dir.'),
  ('Bir optik lifte çekirdeğin indisi 1,5 ve kılıfın indisi 1,2\'dir. Lifin sayısal açıklığı NA = √(n₁² − n₂²) kaçtır?', '0,9', ['0,35', '1,2', '1,5'], 'NA = √(2,25 − 1,44) = √0,81 = 0,9 bulunur.'),
  ('Bir lazer ışını fiber optik kablonun ucundan girerken fiberin kabul açısı büyük olduğunda ne söylenebilir?', 'Çekirdek ve kılıf indisleri farkı büyüktür', ['Kablo çapı çok kalın, çekirdek ise oldukça geniştir', 'Işığın dalga boyu büyüktür', 'Kablonun rengi koyudur'], 'Kabul açısı sin θ_max = NA = √(n₁² − n₂²) ile verilir; indis farkı arttıkça NA ve kabul açısı büyür.'),
  ('Bir sıvıya konan iki ortamın kırılma indisleri birbirine yaklaşırsa sınır açısı nasıl değişir?', 'Artar, 90°\'ye yaklaşır', ['Azalır, 0°\'ye yaklaşır', 'Değişmez', 'Önce artar sonra azalır'], 'sinθ_c = n₂/n₁ ve n₂ → n₁ olunca sinθ_c → 1; θ_c 90°\'ye yaklaşır, tam yansıma zorlaşır.'),
  ('Tepe açısı 60° olan bir prizmada minimum sapma açısı 30° ölçülmüştür. Prizmanın kırılma indisi nedir? (n = sin((A+D)/2)/sin(A/2))', '√2', ['√3', '1,5', '2'], 'n = sin45°/sin30° = (√2/2)/(1/2) = √2 ≈ 1,41 bulunur.'),
  ('Dik üçgen prizmanın hipotenüs yüzüne dik doğrultuda gelen ışın, iki dik yüzünde art arda tam yansıdıktan sonra nasıl çıkar?', 'Gelen ışına paralel, ters yönde', ['Gelen ışınla aynı yönde ve aynı doğru üzerinde', 'Gelen ışına dik', 'Çıkamaz'], 'Işın iki dik yüzde ardışık tam yansıma yapınca yönü 180° döner ve gelen ışına paralel olarak geri gider; dürbünlerde kullanılır.'),
  ('Fotoğraf makinesi objektiflerinde kromatik sapınç (renk sapması) azaltılırken kullanılan akromatik çift mercek hangi malzemelerden yapılır?', 'Farklı dispersiyonlu (crown ve flint) iki cam türünden', ['Aynı cam türünden yapılmış ancak farklı kalınlıkta iki mercekten', 'Plastik ve metalden', 'Yalnız tek kalın camdan'], 'Yakınsak crown ve ıraksak flint camın birleştirilmesiyle farklı renklerin odak farkları birbirini götürür.'),
  ('Odak uzaklığı f olan bir yakınsak mercekle gerçek görüntü elde ediliyor. Cisim ile gerçek görüntü arasındaki uzaklık en az ne kadar olabilir?', '4f', ['2,5f', '3f', '8f'], 'Gerçek görüntüde s + s\' toplamı, s = s\' = 2f iken en küçük değerini alır; bu değer 4f\'dir.'),
  ('Bir cisim ile ekran arasındaki uzaklık 100 cm\'dir. Merceği iki farklı konuma yerleştirdiğinizde ekranda net görüntü oluşuyor ve iki konum arası 60 cm\'dir. Merceğin odak uzaklığı kaç cm\'dir? (Bessel: f = (d² − x²)/4d)', '16', ['25,5', '40', '80'], 'f = (100² − 60²)/(4 × 100) = (10000 − 3600)/400 = 16 cm\'dir.'),
  ('İki özdeş yakınsak mercek, f = 10 cm odak uzaklıklı, aralarında 5 cm mesafe olacak biçimde aynı eksene yerleştiriliyor. Bileşik sistemin odak uzaklığı f = f₁f₂/(f₁ + f₂ − d) bağıntısıyla yaklaşık kaç cm\'dir?', '6,7', ['5', '10,5', '20'], 'f = (10 × 10)/(10 + 10 − 5) = 100/15 ≈ 6,7 cm\'dir.'),
  ('Odak uzaklığı 6 cm olan yakınsak mercekle yapılan büyütecin cismi ne kadar uzağa konmalıdır ki yakın nokta (25 cm) uzaklığında sanal görüntü elde edilsin?', '4,84 cm', ['6 cm', '3 cm', '10,25 cm'], 'Sanal görüntü için s\' = −25: 1/s = 1/f − 1/s\' = 1/6 + 1/25 = 31/150 → s ≈ 4,84 cm.'),
  ('Havadaki odak uzaklığı 20 cm olan çift tümsek cam merceğin (n = 1,5) suya (n = 4/3) daldırıldığında odak uzaklığı için ne söylenir?', 'Artar, yaklaşık 80 cm olur', ['Azalır, yaklaşık 10 cm olur, çünkü sıvı ışığı daha çok kırar', 'Aynı kalır', 'Işınları ıraksatır'], '1/f ∝ (n_mercek/n_ortam − 1): havada 0,5, suda (1,5/1,333 − 1) = 0,125 olduğundan f yaklaşık 4 kat artar, 80 cm olur.'),
  ('Mercekle yapılan bir görüntü ekranda keskin biçimde oluşmuşken mercek ile ekran arasına cam bir levha konursa ekrandaki görüntü ne olur?', 'Odak kayar, görüntü bulanıklaşır', ['Görüntü ters döner ve boyu iki katına çıkar', 'Görüntü hiç etkilenmez', 'Görüntü tamamen kaybolur'], 'Paralel yüzlü levha ışınların yanal kaymasına ve odağın bir miktar uzaklaşmasına yol açar; ekran aynı yerdeyse görüntü hafifçe bulanır.'),
  ('Fotoğraf makinesinde f-sayısı 2\'den 4\'e çıkarıldığında filme ulaşan ışık miktarı kaç katına iner?', '1/4', ['1/2', '1/16', '1/8'], 'Işık akısı açıklık alanıyla yani D²\'yle orantılıdır; N iki katına çıkınca D yarıya, alan 1/4\'e iner.'),
  ('Bir slayt projektörü perdeden iki kat uzaklaştırılıp aynı net görüntü elde edilirken, slayt ile mercek arasındaki uzaklık nasıl değişir?', 'Biraz azaltılır', ['Biraz artırılır', 'Aynı kalır', 'İki katına çıkarılır'], 'Görüntü uzaklaştıkça s\' büyür; 1/s = 1/f − 1/s\' olduğundan s, f\'ye yaklaşır (azalır).'),
  ('Göze giren ışığın büyük bölümünü kırarak retinada odaklayan yapı hangisidir?', 'Kornea, hava-kornea sınırında kırılma indisi farkının büyük olmasıyla', ['Göz merceği, çünkü kalınlığını değiştirebilen tek ve en güçlü kırıcı yapı odur', 'Retina', 'İris'], 'Kırılma indisi farkı en büyük yüzey hava-kornea yüzeyidir; göz kırma gücünün yaklaşık üçte ikisi buradan gelir.'),
  ('Mavi bir filtre ve sarı bir filtre arka arkaya konarak beyaz ışık geçirilirse hangi renk elde edilir?', 'Yeşil veya koyu yeşil', ['Beyaz, çünkü iki filtre tüm renkleri geçirir', 'Mor', 'Kırmızı'], 'Sarı filtre kırmızı ve yeşili, mavi (veya camgöbeği) filtre mavi ve yeşili geçirir; ortak geçen yeşildir. (Çıkarmalı karışım.)'),
  ('Hava (n = 1) içindeki ince bir sabun zarına (n = 1,5) dik gelen 600 nm\'lik ışık yansımada en parlak görünüyorsa zarın olası en küçük kalınlığı kaç nm\'dir? (Yansımada üst yüzeyde π, alt yüzeyde 0 faz değişimi olur.)', '100', ['200,5', '300', '400'], 'Yapıcı girişim için 2nt = λ/2 olmalıdır: t = λ/4n = 600/(4 × 1,5) = 100 nm.'),
  ('Tek yarıkta kırınım deneyinde yarık genişliği a, ışığın dalga boyu λ\'dır. Merkezi aydınlık bandın kenarları, yarık genişliğine göre hangi koşulda belirlenir?', 'a·sinθ = λ', ['a·sinθ = λ/2', 'a·cosθ = λ', 'a = λ·sinθ/2'], 'Birinci karanlık saçak için yol farkı koşulu a·sinθ = λ\'dır; merkezi bandın açısal yarı genişliği bu açıyla verilir.'),
  ('Bir kırınım ağında, görünür ışıkta kaç mertebeye kadar çizgi görülebileceğini belirleyen sınır nedir? (d·sinθ = mλ)', 'sinθ ≤ 1 olması', ['θ ≥ 90° olması', 'm\'nin her zaman sonsuz olması', 'sinθ > 1 olması'], 'sinθ en fazla 1 olabildiğinden m ≤ d/λ koşulu mertebe sayısını sınırlar.'),
  ('Bir kırınım ağında d = 1,5 µm ve ışığın dalga boyu 500 nm ise ekranda en fazla kaç mertebe (her iki yanda ayrı sayarak) aydınlık çizgi görülür?', 'Her iki yanda en fazla 2 mertebe', ['Her iki yanda en fazla 3 mertebe', 'Her iki yanda en fazla 1 mertebe', 'Her iki yanda en fazla 5 mertebe'], 'm ≤ d/λ = 3 olur; ancak m = 3\'te θ = 90° olduğundan görülmez. Dolayısıyla m = 1, 2 görülebilir.'),
  ('Bir lazer işaretçi ışığı ince bir saç telinden geçirilip duvarda incelendiğinde yatay saçak dizisi oluşuyor. Saç telinin kalınlığı arttıkça saçak aralığı nasıl değişir?', 'Azalır', ['Artar', 'Değişmez', 'Önce artar sonra azalır'], 'Babinet ilkesine göre saç teli tek yarık gibi davranır; Δy ∝ λL/a olduğundan kalınlık (a) arttıkça saçaklar sıklaşır.'),
  ('Çaprazlanmış iki polarizör arasına, her ikisine de 45° açıyla üçüncü bir polarizör yerleştirilirse kutuplanmamış I₀ şiddetli ışık için çıkış şiddeti ne olur?', 'I₀/8', ['0', 'I₀/4', 'I₀/2'], 'İlk polarizörden sonra I₀/2; ikinciden I₀/2 × cos²45° = I₀/4; üçüncüden I₀/4 × cos²45° = I₀/8.'),
  ('Gökyüzünün Güneş\'e dik doğrultusundaki ışığı kısmen kutuplanmış görünür. Bunun nedeni nedir?', 'Atmosfer moleküllerinden saçılma sırasında ışığın kutuplanması', ['Atmosferdeki yansıma sonucu', 'Güneşin yüzeyindeki güçlü manyetik alanın ışığı doğrudan polarize yaymasıyla', 'Dünya\'nın manyetik alanı'], 'Rayleigh saçılmasında saçılan ışık, gelen ışına dik doğrultuda belirgin biçimde kutuplanır; bu yüzden polarize gözlükle gökyüzü koyulaşır.'),
  ('Güneş ışığı su yüzeyinde belirli bir açıyla yansıdığında yansıyan ışığın tamamen kutuplanması için gelen ve kırılan ışınlar arasındaki açı kaç derece olmalıdır?', '90', ['60', '45', '180'], 'Brewster açısında yansıyan ve kırılan ışınlar arasındaki açı 90°\'dir; bu durumda yansıyan ışık tam kutuplanır.'),
  ('Polarizörler sıra sıra dizildiğinde ardışık polarizörler arasındaki açılar küçük olduğunda sistem ışığı geçirir. Bu durum, polarlanma düzleminin ne kadarlık bir adımla yavaş yavaş döndürülebileceğini gösterir?', 'Küçük adımlarla neredeyse tüm şiddeti koruyarak döndürülebilir', ['Hiçbir şekilde döndürülemez, çünkü polarizör ışığı yalnızca keser ve çevirmez', 'Yalnızca 90° adımlarla', 'Şiddet sıfırlanarak'], 'Her bir adımda cos²(Δθ) ≈ 1 olduğundan çok sayıda küçük adımla polarlanma düzlemi çevrilirken şiddet çok az azalır.'),
  ('Foucault\'nun 1850\'de döner ayna yöntemiyle yaptığı karşılaştırmalı ölçümün sudaki ışık hızına ilişkin sonucu nedir?', 'Işığın sudaki hızının havadakinden küçük olduğunu göstermiştir', ['Işığın sudaki hızının havadakinden büyük olduğunu', 'Işığın boşlukta yayılamadığını ve ortam gerektirdiğini kanıtlamıştır', 'Işığın kütleli olduğunu'], 'Foucault suda ışığın hızını da ölçmüş, havadakinden küçük bulmuştur; bu, Newton\'un tanecik modelinin öngördüğü sonucun tersidir ve dalga modelini destekler.'),
  ('Güneş\'in yarıçapı Ay\'ınkinden yaklaşık 400 kat büyük, Dünya-Güneş uzaklığı da Dünya-Ay uzaklığından yaklaşık 400 kat büyüktür. Bu durumun sonucu nedir?', 'Gökyüzünde Güneş ve Ay\'ın açısal çapları yaklaşık eşit görünür', ['Güneş, Ay\'dan çok daha küçük görünür ve tutulma hiçbir zaman tam olamaz', 'Ay Güneş\'ten çok büyük görünür', 'Güneş tutulması hiç olmaz'], 'Açısal çap ≈ yarıçap/uzaklık oranı aynı olduğundan iki cismin görünen büyüklükleri yaklaşık eşittir; bu yüzden tam Güneş tutulması mümkündür.'),
  ('Işık şiddeti 3 kat daha az olan bir lamba, ekranı ilk lambayla aynı aydınlatmak için ilk lambanın uzaklığına göre nasıl bir uzaklığa konmalıdır?', '√3 kat daha yakına', ['3 kat daha yakına', '√3 kat daha uzağa', '3 kat daha uzağa'], 'E sabit tutulurken I/r² sabittir; I 3 kat azalırsa r² 3 kat azalır ve r, √3 kat küçülür.'),
  ('Gökyüzü mor ışığın daha çok saçılmasına rağmen neden mor değil mavi görünür?', 'Güneş tayfında mor azdır, atmosfer bir kısmını soğurur ve gözümüz maviye daha duyarlıdır', ['Mor ışık saçılmaz', 'Atmosferde mor yoktur', 'Gözümüz mora tamamen kördür'], 'Güneş mor bölgede daha az enerji verir, atmosfer ve ozon mor-morötesini soğurur; göz duyarlılığı da maviye daha yüksektir.'),
  ('Soğuk deniz yüzeyi üstünde sıcak hava katmanı varken uzaktaki bir geminin gökyüzünde havada asılı veya ters görülmesi hangi olaya yol açar?', 'Üst serap', ['Alt serap', 'Gökkuşağı', 'Hale'], 'Soğuk deniz üstündeki yoğun hava ile sıcak üst katman arasında ışınlar aşağı doğru bükülür; uzaktaki cisim yukarıda görünür.'),
  ('Atmosferin kırma etkisi nedeniyle Güneş ufuktan aşağıda olmasına rağmen yaklaşık kaç dakika önce görülebilir? (yaklaşık değer)', 'Yaklaşık 2 dakika', ['Yaklaşık 2 saat', 'Yaklaşık 20 saniye', 'Yaklaşık 20 dakika'], 'Atmosferik kırılma Güneş\'i ufuktan yaklaşık 0,5° yüksekte gösterir; bu da gündüzü yaklaşık 2–4 dakika uzatır.'),
  ('Yağmurdan sonra gökkuşağının yüksekliği Güneş\'in ufuktan yüksekliğine göre nasıl değişir?', 'Güneş yükseldikçe gökkuşağı alçalır', ['Güneş yükseldikçe gökkuşağı yükselir', 'Yüksekliği değişmez', 'Her zaman tepe noktasındadır'], 'Gökkuşağı, Güneş\'in karşı noktasından yaklaşık 42° yarıçaplı bir çemberdir; Güneş yükseldikçe yarım dairenin görünen kısmı azalır ve alçalır.'),
  ('Huygens\'in ışık dalgası kuramına göre ışığın daha yoğun ortamda yavaşlaması gerektiği sonucu hangi modelle çelişir?', 'Newton\'un tanecik modelinin ışığın daha yoğun ortamda hızlandığı öngörüsüyle', ['Maxwell\'in elektromanyetik kuramıyla', 'Planck\'ın kuantum kuramıyla', 'Einstein\'ın görelilik kuramıyla'], 'Newton kırılmayı yoğun ortamda tanecik hızının artmasıyla açıklıyordu; Huygens ise hız azalır diyordu. Foucault deneyi Huygens\'i doğruladı.'),
  ('Dalga cephesi, bir ortamdan diğerine geçerken sınırla bir α açısı yapıyorsa Huygens yapısına göre kırılma yasasının sinα₁/sinα₂ = v₁/v₂ ifadesi hangi geometrik gerçeğe dayanır?', 'Aynı sürede iki ortamda yayılan dalgacıkların farklı yol alması', ['Işığın frekansının değişmesi', 'Dalgaların genliğinin azalması', 'Cephenin eğrisinin sabit olması'], 'Aynı Δt\'de v₁Δt ve v₂Δt yolları alınır; cephenin sınırdaki dönüşü bu yol oranlarından sinüs bağıntısını verir.'),
  ('Işık hızının 1849\'daki Fizeau deneyi ile yaklaşık değeri bulunmuştur. Bu deneyin ilkesi nedir?', 'Işığın uzaktaki aynaya gidip dönerken dönen dişli çarkın dişleri arasından geçmesi', ['Işığın cam prizmada kırılması', 'Ay\'ın tutulmasının izlenmesi', 'Işığın polarlanması'], 'Dişli çark hızı ayarlanınca ışık dişler arasından giderken dönüşte bir dişe çarpar; hız ve diş sayısından ışık hızı hesaplanır.'),
  ('Fizeau deneyinde dişli çark ile ayna arasındaki uzaklık 8630 m idi. Çark 720 dişli ve ışık geri dönerken ilk kez kaybolduğunda saniyede 12,6 devir yapıyorsa ışık hızı yaklaşık kaç m/s bulunur? (Işık gidip dönerken çark yarım diş aralığı döner.)', '3,1 × 10⁸', ['1,6 × 10⁸', '6,3 × 10⁸', '3,1 × 10⁷'], 'Çarkın yarım diş aralığı dönme süresi t = 1/(2 × 720 × 12,6) ≈ 5,5 × 10⁻⁵ s. v = 2 × 8630/5,5 × 10⁻⁵ ≈ 3,1 × 10⁸ m/s.'),
  ('Bir yay ortasından ikiye kesilip yarım yaya aynı kütle asılırsa salınım frekansı nasıl değişir?', '√2 kat artar', ['İki katına çıkar', 'Yarıya iner', 'Değişmez'], 'Yarım yayın yay sabiti 2 katına çıkar; f ∝ √k olduğundan frekans √2 kat artar.'),
  ('Genliği A olan basit harmonik hareket yapan bir cismin denge konumundan geçerkenki hızı v_max ise uzanımın A/2 olduğu anda hızı kaçtır?', '(√3/2)·v_max', ['v_max/2', 'v_max/4', 'v_max·√2'], 'Enerjiden v = ω√(A² − x²) = ω·A·√(1 − 1/4) = (√3/2)v_max olur.'),
  ('Düşey yay-kütle sisteminin periyodu, aynı sistemin yatay düzlemde (sürtünmesiz) periyoduna göre nasıldır?', 'Aynıdır', ['Düşeyde daha uzundur', 'Yatayda daha uzundur', 'Düşeyde sıfırdır'], 'Ağırlık yalnız denge konumunu kaydırır; geri çağırıcı kuvvet k·x olduğundan periyot T = 2π√(m/k) her iki durumda aynıdır.'),
  ('Zemin sarsıntısına dayanıklı yüksek binalarda tepeye yerleştirilen büyük kütleli sarkaç (sönümleyici) depremde titreşimi nasıl azaltır?', 'Binanın doğal frekansında ters faz titreşerek enerjiyi soğurur', ['Binayı ağırlaştırarak sabitler', 'Zemini sertleştirir', 'Işığı yansıtır'], 'Ayarlı kütle sönümleyici binanın doğal frekansına akort edilir ve ters fazlı hareketiyle yapısal titreşimi azaltır.'),
  ('AM radyo dalgalarının geceleri gündüze göre çok daha uzak istasyonlardan alınabilmesinin nedeni nedir?', 'Gece iyonosferin yansıtıcılığının artması', ['Gece havanın soğuması', 'Gece Ay\'ın radyo yayması', 'Gece frekansın artması'], 'Gece D katmanı kaybolur; iyonosfer AM dalgalarını yeryüzüne yansıtır ve çok uzak mesafelere ulaşır.'),
  ('Bir anten uzunluğunun yayın yapılan dalga boyunun yarısı (λ/2) alınmasının nedeni nedir?', 'Anten üzerinde rezonansla duran dalga oluşturup verimi artırmak', ['Anteni hafifletmek', 'Işığı yansıtmak', 'Elektrik direncini sıfırlamak'], 'Yarım dalga antende duran akım dalgası oluşur ve verimli ışıma gerçekleşir; bu yüzden anten boyu dalga boyuyla ilişkilidir.'),
  ('Uzay sondalarından gelen radyo sinyalinin Dünya\'ya ulaşması 1 saat sürüyorsa sonda Dünya\'dan yaklaşık kaç astronomik birim uzaktadır? (1 AB ≈ 500 ışık saniyesi)', '7,2', ['3,6', '14,4', '0,5'], '1 saat = 3600 s; 3600/500 = 7,2 AB.'),
  ('Odak uzaklığı 10 cm olan yakınsak mercek ile odak uzaklığı −10 cm olan ıraksak mercek 5 cm arayla aynı eksene dizilmiştir. Sonsuzdaki bir cismin son görüntüsü ıraksak mercekten itibaren nerede oluşur?', 'Arkasında 10 cm uzaklıkta', ['Önünde 10 cm uzaklıkta', 'Arkasında 5 cm uzaklıkta', 'Sonsuzda'], 'İlk mercek görüntüyü 10 cm\'de oluştururken ikinci merceğe göre bu görüntü 5 cm arkada, yani sanal cisimdir (s = −5). 1/s\' = −1/10 + 1/5 = 1/10 → s\' = +10 cm.'),
  ('Odak uzaklığı 15 cm olan bir yakınsak mercekten 30 cm uzağa konan cismin arkasına, birinciden 50 cm uzağa odak uzaklığı 20 cm olan ikinci bir yakınsak mercek konuyor. Son görüntü nerede oluşur?', 'Sonsuzda', ['İkinci merceğin 20 cm arkasında', 'İkinci merceğin 10 cm önünde', 'İkinci merceğin 40 cm arkasında'], 'İlk mercek 30 cm\'de gerçek görüntü verir. Bu görüntü ikinci merceğe 20 cm uzaktadır ve tam odak noktasındadır; ışınlar paralel çıkar, görüntü sonsuzda oluşur.'),
  ('Bir kabın dibinde 6 cm kalınlığında cam (n = 1,5) levha, üstünde 8 cm yüksekliğinde su (n = 4/3) vardır. Yukarıdan dik bakan göz kabın dışındaki yüzeyin dibini yüzeyden kaç cm aşağıda görür?', '10', ['14,5', '7', '12'], 'Görünür derinlik her katman için t/n toplanarak bulunur: 8/(4/3) + 6/1,5 = 6 + 4 = 10 cm.'),
  ('Kalınlığı 3 cm ve kırılma indisi 1,5 olan cam levhanın arkasındaki bir cisme levhaya dik doğrultuda bakıldığında cisim gözlemciye kaç cm yaklaşmış görünür?', '1', ['2', '0,5', '3'], 'Kayma miktarı t(1 − 1/n) = 3 × (1 − 1/1,5) = 3 × (1/3) = 1 cm\'dir.'),
  ('Bir CD\'nin üzerindeki çukur ve düzlük yapılar lazerle okunurken bilgi nasıl elde edilir?', 'Çukurdan ve düzlükten yansıyan ışığın girişiminden oluşan şiddet farklarıyla', ['Işığın kırılmasıyla', 'Ses dalgalarıyla', 'Mıknatıslanmayla'], 'Çukur derinliği λ/4 olarak seçildiğinde çukurdan ve çevreden yansıyan ışınlar yıkıcı girişim yapar; yansıyan şiddet değişir.'),
  ('Bir lazer işaretçinin 650 nm\'lik ışığı, 1 mm genişliğindeki bir ışın olarak 100 m ötedeki duvara gönderiliyor. Işın genişliği kırınım nedeniyle yaklaşık nasıl değişir? (θ ≈ λ/D)', 'Yaklaşık 6,5 cm\'ye genişler', ['Değişmez', 'Yaklaşık 6,5 m olur', 'Yaklaşık 0,65 mm olur'], 'θ ≈ 650 × 10⁻⁹/10⁻³ = 6,5 × 10⁻⁴ rad; 100 m\'de genişleme ≈ 6,5 cm olur.'),
  ('Ultrason temizleyicilerde (örneğin takı temizliğinde) kullanılan yüksek frekanslı titreşimin etkisi nedir?', 'Sıvıdaki küçük kabarcıkların çökmesiyle yüzeydeki kiri koparan mikro şok dalgaları oluşması', ['Işığın kırılması', 'Sıvının donması', 'Manyetik çekim'], 'Ultrasesle oluşan kavitasyon kabarcıkları patlayarak yüzeye yakın küçük şok dalgaları üretir.'),
  ('Poisson, Fresnel\'in dalga kuramını çürütmek için hangi öngörüyü yapmıştır; deney sonucu bu öngörü hakkında ne göstermiştir?', 'Dairesel engelin gölgesinin ortasında parlak nokta çıkacağını; deneyde bu nokta gerçekten görüldü', ['Gölgede karanlık halka çıkacağını; hiç görülmedi', 'Gölgenin kaybolacağını; görüldü', 'Işığın saçılmayacağını; görülmedi'], 'Dalga kuramı dairesel engelin gölgesinin merkezinde parlak bir nokta öngörür. Poisson bunu saçma buldu, ancak Arago deneyi yaptığında nokta gözlendi.'),
  ('Işığın kutuplanmasına ilişkin ilk gözlemler hangi bilimsel görüşün sınırlarını göstermiştir?', 'Işığın boyuna dalga olduğu görüşünün yetersiz olduğunu', ['Işığın tanecik olduğunu', 'Işığın hızının sonsuz olduğunu', 'Işığın eterde yayılmadığını'], 'Kutuplanma yalnız enine dalgalarda gözlenir; bu nedenle Young ve Fresnel ışığın enine dalga olması gerektiği sonucuna vardılar.'),
  ('Gözbebeği çapı 4 mm olan gözün 550 nm ışık için kırınım sınırlı ayırma açısı θ = 1,22λ/D kaç radyandır?', '1,7 × 10⁻⁴', ['1,7 × 10⁻⁷', '3,4 × 10⁻⁴', '1,7 × 10⁻³'], 'θ = 1,22 × 550 × 10⁻⁹/4 × 10⁻³ ≈ 1,68 × 10⁻⁴ rad.'),
  ('Birbirinden 2 × 10⁻⁷ rad açısal uzaklıktaki iki yıldızı ayırt edebilmek için görünür ışık (550 nm) kullanan bir teleskobun objektif çapı en az yaklaşık kaç metre olmalıdır? (θ = 1,22λ/D)', '3,4', ['0,34', '34', '0,034'], 'D = 1,22λ/θ = 1,22 × 550 × 10⁻⁹/2 × 10⁻⁷ ≈ 3,36 m.'),
  ('Radyo teleskopların çok büyük çanaklı olması ya da birkaç teleskobun birleştirilmesinin (interferometre) nedeni nedir?', 'Radyo dalga boyunun büyük olması nedeniyle kırınım sınırını küçültmek için çok geniş açıklık gerekmesi', ['Radyo dalgalarının yavaş olması', 'Radyo dalgalarının gözle görülmesi', 'Radyo dalgalarının enine olması'], 'θ ∝ λ/D ve radyo λ\'sı görünür ışıktan çok büyüktür; eşit çözünürlük için D çok büyük olmalıdır. Çanak ağlarıyla büyük açıklık sentezlenir.'),
  ('Bir fotoğraf makinesinde diyafram çok kapatıldığında (f/32 gibi) görüntü keskinliği neden bir noktadan sonra azalabilir?', 'Küçük açıklıkta kırınımın artması', ['Işığın aşırı artması', 'Merceğin ısınması', 'Kırılma indisinin değişmesi'], 'Çok küçük açıklıkta ışık kırınımla yayılır ve nokta görüntüler büyür; keskinlik düşer.'),
  ('Çok ince bir altın tabakanın (altın yaprak) yeşil-mavi ışığı geçirmesi nasıl açıklanır?', 'Metalin ince tabakasında soğurma ve yansıma seçicidir; bazı dalga boyları daha kolay geçer', ['Altının saydam olması', 'Altının ışığı kırması', 'Işığın polarlanması'], 'Çok ince metal filmlerde elektronların ışıkla etkileşimi dalga boyuna bağlıdır; yeşil-mavi bölgede geçirgenlik görece yüksektir.'),
  ('Frekansı 850 Hz olan bir kaynaktan ses hızı 340 m/s iken kaynak 34 m/s ile uzaklaşırken, durgun gözlemci kaç Hz duyar? Bulduğunuz değeri gözlemci aynı hızla uzaklaşıyor ve kaynak durgun olsaydı duyacağı değerle karşılaştırınız. Hangisi doğrudur?', '772,7 Hz; gözlemci uzaklaşırsa 765 Hz duyardı', ['765 Hz; iki durumda da aynıdır', '850 Hz; iki durumda da değişmez', '772,7 Hz; iki durumda da aynıdır'], 'Kaynak uzaklaşırken f\' = 850 × 340/374 ≈ 772,7 Hz; gözlemci uzaklaşırken f\' = 850 × 306/340 = 765 Hz. Doppler değişimi kaynağın mı gözlemcinin mi hareket ettiğine bağlıdır.'),
  ('Haas (öncelik) etkisi nedir?', 'İlk gelen sesin yönü belirleyici olur, kısa gecikmeli yankı ayrı bir ses olarak algılanmaz', ['Yankının her zaman duyulması', 'Sesin hızının artması', 'Sesin frekansının düşmesi'], 'Yaklaşık 30–50 ms içinde gelen yansımalar ilk gelen sesle birleşik algılanır ve kaynağın yönü ilk gelen sese göre belirlenir.'),
  ('Piyanoda aynı notanın üç telinin hafifçe farklı frekansa akort edilmesinin müzikal sonucu nedir?', 'Hafif vuru oluşturarak tınıyı zenginleştirir ve sesin uzun süre duyulmasını sağlar', ['Sesin daha pes olması', 'Sesi tamamen kesmesi', 'Hiçbir etki yapmaması'], 'Teller arası küçük frekans farkı yavaş vuru yaratır; korus etkisi gibi daha dolgun ve canlı ses elde edilir.'),
  ('Bir lamba tavanda iken masanın tam altındaki nokta ile 60° açıyla bakılan nokta arasında aydınlanma farkı vardır. Aynı yükseklikte lambanın alt noktasından uzaklaştıkça aydınlanma neden azalır?', 'Hem uzaklık artar hem de ışının gelme açısı büyüyüp cosα küçülür', ['Yalnız lamba söner', 'Işık yansır', 'Işık rengi değişir'], 'E = I·cosα/r² olduğundan yanal noktalarda r büyür ve α artar; her ikisi de aydınlanmayı azaltır.'),
  ('Havadan (340 m/s) suya (1500 m/s) geçen ses dalgası için tam yansıma olayı hangi geçişte ve yaklaşık hangi sınır açısından büyük gelme açılarında gerçekleşir?', 'Havadan suya geçerken, yaklaşık 13°\'den büyük açılarda', ['Sudan havaya geçerken, yaklaşık 13°\'den büyük açılarda', 'Havadan suya geçerken, yaklaşık 77°\'den büyük açılarda', 'Sudan havaya geçerken, yaklaşık 77°\'den büyük açılarda'], 'Tam yansıma, dalganın yavaş ortamdan hızlı ortama geçtiği durumda olur (ışığın camdan havaya geçişi gibi). sinθc = v_hava/v_su = 340/1500 ≈ 0,227 → θc ≈ 13°.'),
  ('Gücü 0,1 W olan noktasal bir ses kaynağı açık alanda yayıyor. 10 m uzaktaki ses şiddeti düzeyi yaklaşık kaç dB\'dir? (I₀ = 10⁻¹² W/m², π = 3,14; küresel yayılım)', '79', ['58', '100', '120'], 'I = P/(4πr²) = 0,1/(4 × 3,14 × 100) ≈ 8 × 10⁻⁵ W/m²; β = 10·log(8 × 10⁻⁵/10⁻¹²) ≈ 79 dB.'),
  ('Bir fiber optik kabloda sinyal zayıflaması 0,2 dB/km ise 100 km uzunluğunda toplam kayıp kaç dB\'dir ve çıkış gücü girişin kaçta kaçıdır?', '20 dB; yüzde 1', ['20 dB; yüzde 10', '2 dB; yüzde 63', '200 dB; yüzde 0,01'], '0,2 × 100 = 20 dB kayıp; güç oranı 10^(−20/10) = 10⁻² = %1\'dir.'),
  ('Sismik dalgaların yer içinde yayılırken yoğunluğun arttığı katmanlara doğru ilerlerken hızlarının genellikle artması nedeniyle yollar nasıl bir eğri izler?', 'Yüzeye doğru bükülen (içbükey) eğriler', ['Düz doğrular', 'Yer merkezine doğru dik inen doğrular', 'Kapalı çemberler'], 'Derinlikle hız arttığından dalga cepheleri yukarı doğru dönerek kırılır; ışınlar yüzeye doğru bükülür.'),
  ('Ultrasonik görüntülemede doku sınırlarında yansıyan sesin şiddeti hangi niceliğe bağlıdır?', 'İki doku arasındaki akustik empedans farkına', ['Dokunun rengine', 'Dokunun sıcaklığına yalnız', 'Probun şekline yalnız'], 'Yansıma katsayısı R = ((Z₂ − Z₁)/(Z₂ + Z₁))² olduğundan empedans farkı büyük sınırlarda (kemik-doku) yansıma güçlüdür.'),
  ('Çıplak gözle iki yakın yıldızın ayrı görülebilmesi için gerekli en küçük açıya göre, açısal ayırma sınırı 1 yay dakikası olan göz Ay\'ın yüzeyinde (385 000 km) en küçük hangi uzaklıktaki iki noktayı ayırt edebilir? (1\' ≈ 2,9 × 10⁻⁴ rad)', 'Yaklaşık 110 km', ['Yaklaşık 11 km', 'Yaklaşık 1100 km', 'Yaklaşık 11 000 km'], 'Uzaklık = açı × mesafe = 2,9 × 10⁻⁴ × 385 000 ≈ 112 km.'),
  ('Hava kabarcığı su içinde ince kenarlı mercek gibi bir şekle sahipse (çift tümsek hava boşluğu) su içindeki ışın demetine ne yapar?', 'Işınları ıraksatır, çünkü hava suya göre daha az kırıcıdır', ['Işınları toplar', 'Işınları sapmadan geçirir', 'Işınları tam yansıtır'], 'Kırıcılığı çevresinden küçük olan ortamda çift tümsek biçimli bir mercek ıraksak davranır; ince kenarlı olmasına rağmen ışınları toplamaz.'),
  ('Mercekle yapılan bir görüntünün netliğini bozan küresel sapınç (aberasyon) nasıl azaltılır?', 'Işığı yalnız merceğin orta bölgesinden geçirecek şekilde diyaframı kapatarak', ['Merceğin rengini değiştirerek', 'Işığı polarlayarak', 'Işığın dalga boyunu artırarak'], 'Küresel sapınç merceğin kenarından geçen ışınların daha çok kırılmasından doğar; diyaframı kısmak yalnız merkez ışınları kullanarak sapınçı azaltır.'),
  ('Bir dalga paketinin (grup) hızı ile onu oluşturan tek dalgaların faz hızı için hangisi doğrudur?', 'Dispersif ortamda farklı olabilirler; enerji ve bilgi grup hızıyla taşınır', ['Her ortamda daima eşittirler ve tek bir değer alırlar', 'Faz hızı her zaman ışık hızını aşamaz, grup hızı ise sonsuz olabilir', 'Grup hızı dalga boyundan bağımsız olarak her zaman sıfırdır'], 'Dispersif ortamda faz hızı frekansa bağlıdır; dalga paketi zarfı grup hızıyla ilerler ve enerji ile bilgi grup hızıyla taşınır.'),
  ('İpteki bir dalganın genliği ve frekansı aynı kalırken ipin birim uzunluk kütlesi dört katına çıkarılır. Gerilme sabit ise dalganın taşıdığı güç nasıl değişir? (P ∝ √(μT)·ω²A²)', 'İki katına çıkar', ['Dört katına çıkar', 'Yarıya iner', 'Değişmez'], 'P ∝ √μ olduğundan μ dört katına çıkınca güç √4 = 2 katına çıkar.'),
  ('Bir dalga kaynağı yayılma doğrultusuna dik doğrultuda hareket ediyor ise gözlemciye göre hızı değişir mi ve Doppler etkisi olur mu?', 'Doğrultuya dik hareket ilk yaklaşımda Doppler kayması oluşturmaz; yalnız yaklaşma-uzaklaşma bileşeni etkilidir', ['Doppler etkisi en büyük olur', 'Frekans iki katına çıkar', 'Frekans her zaman sıfır olur'], 'Doppler kayması, kaynak ile gözlemciyi birleştiren doğru boyunca hız bileşenine bağlıdır; dik bileşen sıfır kayma verir.'),
  ('Bir cam levha yatay biçimde su yüzeyinin üzerine konup üstünden ışık geçiriliyor. Su-cam sınırından ışığın geçişinde hangi büyüklüğün korunduğunu söyleyebiliriz?', 'n·sinθ çarpımı katmanların tümünde aynı kalır', ['Işığın dalga boyu aynı kalır', 'Işığın hızı aynı kalır', 'Işık şiddeti aynı kalır'], 'Snell yasasının genelleştirilmiş hâli: paralel katmanlarda n₁sinθ₁ = n₂sinθ₂ = n₃sinθ₃ = ... sabittir.'),
  ('Bir lazer ışını cam levhaya 45° ile giriyor ve levhayı tam yansımayla terk edemiyor. Bunun sebebi nedir?', 'Paralel yüzlü levhada çıkış yüzeyindeki gelme açısı, girişteki kırılma açısına eşittir ve sınır açısından küçüktür', ['Işık levhada soğurulur', 'Işık frekansını değiştirir', 'Işık levhada yavaşlar'], 'Paralel yüzlü levhada çıkıştaki gelme açısı girişteki kırılma açısına eşit olduğundan sınır açısından küçüktür; bu yüzden ışık dışarı çıkabilir.'),
  ('Aynı ışık bir ortamdan geçerken optik yolu (n·d) neden önemli bir niceliktir?', 'Girişimde faz farkını belirler; iki yol arasındaki n·d farkı fazı verir', ['Işığın rengini belirler', 'Işığın şiddetini belirler', 'Işığın kutuplanmasını belirler'], 'Faz farkı = 2π·Δ(n·d)/λ₀ olduğundan, farklı ortamlardan geçen ışınların girişimi optik yol farkıyla belirlenir.'),
  ('Çift yarık deneyinde yarıklardan biri kırılma indisi 1,5 olan 2 µm kalınlıkta ince bir levhayla kapatılırsa optik yol farkı ne kadar değişir?', '1 µm', ['3 µm', '0,5 µm', '2 µm'], 'Ek optik yol = (n − 1)·t = 0,5 × 2 µm = 1 µm; bu fark merkezi saçağı kaydırır.'),
  ('Kayma (S) dalgalarının hızı v = √(G/ρ) bağıntısıyla verilir. Kayma modülü 3 × 10¹⁰ Pa, yoğunluğu 3000 kg/m³ olan kayaçta S dalgasının hızı yaklaşık kaç km/s\'dir?', '3,2', ['10', '1,05', '32'], 'v = √(3 × 10¹⁰/3000) = √(10⁷) ≈ 3162 m/s ≈ 3,2 km/s.'),
  ('İnsan kulak zarının alanı yaklaşık 0,5 cm²\'dir. Ses şiddeti 10⁻⁶ W/m² olan bir ses kulak zarına yaklaşık kaç watt güç iletir?', '5 × 10⁻¹¹', ['5 × 10⁻⁶', '5 × 10⁻⁹', '5 × 10⁻¹⁵'], 'P = I·A = 10⁻⁶ × 0,5 × 10⁻⁴ = 5 × 10⁻¹¹ W bulunur.'),
  ('Elektrik gücü 100 W olan bir hoparlörün verimi %1 ise ürettiği ses gücü 1 W\'tır. Açık alanda 10 m uzaktaki ses şiddeti düzeyi yaklaşık kaç dB\'dir? (I₀ = 10⁻¹² W/m², π = 3,14)', '89', ['60', '120', '40'], 'I = 1/(4 × 3,14 × 100) ≈ 8 × 10⁻⁴ W/m²; β = 10·log(8 × 10⁻⁴/10⁻¹²) ≈ 89 dB.'),
  ('Güneş ufuktan 30° yukarıdayken birincil gökkuşağının (ana yay) en yüksek noktası ufuktan yaklaşık kaç derece yukarıda görülür? (Yay, Güneş\'in karşı noktasından 42° yarıçaplıdır.)', '12', ['42,5', '72', '30'], 'Karşı nokta ufkun 30° altındadır; yayın tepe noktası 42° − 30° = 12° yükseklikte görülür.'),
  ('Ufka yakın Güneş neden yassılaşmış (dikeyde basık) görünür?', 'Atmosferde kırılma, alt kenarı üst kenara göre daha çok yükseltir', ['Güneş gerçekten yassıdır', 'Işık yansıma yapar', 'Güneş ufukta küçülür'], 'Alt kenardan gelen ışınlar atmosferde daha uzun yol aldığı için daha çok kırılır; alt kenar daha çok yükselir ve disk dikeyde basık görünür.'),
  ('Birincil ve ikincil gökkuşakları arasında kalan gökyüzü bölgesi neden çevresinden daha koyu görünür (Alexander karanlık bandı)?', 'Bu bölgeye yağmur damlalarından gelen ışığın saçılmaması', ['Bu bölgede damlaların çok büyük olması', 'Işığın tamamen soğurulması', 'Bölgede kırınımla ışığın kaybolması'], 'Birinci yay yaklaşık 42°, ikinci yay yaklaşık 51° yarıçaplıdır; aradaki açılarda damlalardan göze doğru yansıyan ışık yoktur, bu yüzden bölge daha koyu görünür.'),
  ('Güneş ufuktan 20° yukarıdayken ikincil gökkuşağının (51° yarıçaplı) en yüksek noktası ufkun yaklaşık kaç derece yukarısında görülür?', '31', ['51,5', '71', '20'], 'Karşı nokta ufkun 20° altındadır; 51° − 20° = 31° yükseklikte görülür.'),
  ('Gün doğarken veya batarken çok kısa süre görülebilen \'yeşil ışın\' olayı hangi iki fiziksel etkinin birleşimiyle ortaya çıkar?', 'Atmosferik kırılma ve ışığın renklerine ayrılması', ['Kırınım ve girişim', 'Polarlanma ve soğurma', 'Rayleigh saçılması ve tam yansıma'], 'Ufka yakın Güneş\'in üst kenarında atmosfer ışığı bir prizma gibi renklere ayırır; kırmızı alttan, yeşil-mavi üstten kalır ve mavi saçıldığı için son anda yeşil görülür.'),
  ('Güneş ışığının dik olarak düştüğü tam soğurucu bir yüzeye uyguladığı ışınım basıncı P = I/c ile verilir. I = 1360 W/m² için bu basınç yaklaşık kaç Pa\'dır? (c = 3 × 10⁸ m/s)', '4,5 × 10⁻⁶', ['4,5 × 10⁻³', '1360', '3 × 10⁸'], 'P = 1360/(3 × 10⁸) ≈ 4,5 × 10⁻⁶ Pa\'dır; çok küçük bir değerdir.'),
  ('Aynı ışık demeti için tam yansıtıcı bir yüzeye uygulanan ışınım basıncı, tam soğurucu yüzeye uygulananın kaç katıdır?', '2', ['1', '0,5', '4'], 'Yansımada ışığın momentumu tersine döndüğünden verilen momentum değişimi iki katı olur: P = 2I/c.'),
  ('Okyanusta yaklaşık 1000 m derinlikte bulunan ses kanalında (SOFAR) düşük frekanslı seslerin binlerce km uzağa taşınabilmesinin nedeni nedir?', 'Ses hızının bu derinlikte minimum olması ve ses ışınlarının kırılarak kanal içinde hapsolması', ['Suyun burada donması', 'Sesin ışık hızına çıkması', 'Sesin burada yansıma yapmaması'], 'Derinlikle sıcaklık ve basınç etkileri ses hızının bir minimumundan geçmesine yol açar; ışınlar bu minimuma doğru kırılarak kanal içinde yayılır.'),
  ('Gözlük camlarına uygulanan yansıma önleyici kaplamalar yeşil-sarı ışık için tasarlanırsa yansıyan ışıkta hangi renk baskın görünür?', 'Mor-mavimsi', ['Yeşil', 'Sarı', 'Beyaz'], 'Kaplama ortadaki dalga boyunu (yeşil-sarı) yıkıcı girişimle yok eder; yansımada kalan kırmızı ve mor uçların karışımı mor-mavimsi görünür.'),
];
